fn app_data_dir() -> Option<PathBuf> {
    let appdata = std::env::var_os("APPDATA")?;
    Some(PathBuf::from(appdata).join(APP_DIR))
}

fn live2d_core_file() -> Option<PathBuf> {
    app_data_dir().map(|dir| dir.join("live2d").join("Live2DCubismCore.dll"))
}

fn status() -> VideoExportStatus {
    let installed = live2d_core_file().filter(|path| path.is_file());
    VideoExportStatus {
        supported: supported(),
        live2d_core: installed.is_some(),
        live2d_path: installed.map(|path| path.to_string_lossy().to_string()),
    }
}

#[tauri::command]
pub fn video_export_status() -> VideoExportStatus {
    status()
}

/// 导入用户自备的 Cubism Core DLL。
#[tauri::command]
pub fn import_cubism_core(source: String) -> Result<VideoExportStatus, String> {
    let source = PathBuf::from(source);
    if source.file_name().and_then(|name| name.to_str()) != Some("Live2DCubismCore.dll") {
        return Err("请选择 Live2DCubismCore.dll".into());
    }
    let target = live2d_core_file().ok_or("无法定位应用数据目录")?;
    if let Some(parent) = target.parent() {
        std::fs::create_dir_all(parent).map_err(|error| format!("创建目录失败: {error}"))?;
    }
    std::fs::copy(&source, &target).map_err(|error| format!("复制 Cubism Core 失败: {error}"))?;
    Ok(status())
}

