#[tauri::command]
pub async fn export_video(
    app: AppHandle,
    state: State<'_, Arc<VideoExportState>>,
    project_path: String,
    output_path: String,
    start_scene: Option<String>,
    options: Option<VideoExportOptions>,
) -> Result<VideoExportResult, String> {
    let project = PathBuf::from(&project_path);
    if !project.join("game").is_dir() {
        return Err(format!("不是 WebGAL 项目（缺少 game/）: {project_path}"));
    }
    let output = PathBuf::from(&output_path);
    ensure_parent(&output)?;

    let mut export_options = ExportOptions::new(&project);
    export_options.start_scene = start_scene.filter(|scene| !scene.trim().is_empty());
    let mut encoder = EncoderChoice::Auto;
    let mut bitrate_kbps = 0;
    let mut audio_only = false;

    if let Some(config) = options {
        if let Some(height) = config.resolution {
            // 只收预设高度; 宽度由 build_plan 按 Stage_Width/Stage_Height 推导。
            export_options.config.video.auto_width = true;
            export_options.config.video.height = height.clamp(240, 4320);
        }
        if let Some(fps) = config.fps {
            export_options.config.video.fps = fps;
        }
        if let Some(bitrate) = config.bitrate_kbps {
            bitrate_kbps = bitrate;
        }
        if let Some(value) = config.encoder.as_deref() {
            encoder = match value {
                "mf" => EncoderChoice::MediaFoundation,
                "ffmpeg" => EncoderChoice::Ffmpeg,
                _ => EncoderChoice::Auto,
            };
        }
        if let Some(enabled) = config.include_audio {
            export_options.config.audio.enabled = enabled;
        }
        let ui_only = config.ui_only.unwrap_or(false);
        let stage_only = config.stage_only.unwrap_or(false);
        if ui_only {
            export_options.config.layers.background = false;
            export_options.config.layers.figures = false;
        }
        if stage_only {
            export_options.config.layers.ui = false;
        }
        audio_only = config.audio_only.unwrap_or(false);
        export_options.config.audio_only = audio_only;
        if let Some(mode) = config.figure_side.as_deref() {
            export_options.config.figure_side = match mode {
                "legacy" => webgal_video_export::config::FigureSideMode::Legacy,
                "modern" => webgal_video_export::config::FigureSideMode::Modern,
                _ => webgal_video_export::config::FigureSideMode::Auto,
            };
        }
        if let Some(disable) = config.disable_filters {
            export_options.config.disable_filters = disable;
        }
        if let Some(speed) = config.auto_speed {
            export_options.config.timing.auto_speed = speed.min(100);
        }
        if let Some(speed) = config.text_speed {
            export_options.config.timing.text_speed = speed.min(100);
        }
        if let Some(scale) = config.font_scale {
            export_options.config.font_scale = scale.clamp(0.5, 2.0);
        }
        if let Some(selected) = config.selected {
            export_options.config.choices.overrides = selected;
        }
    }

    let log_path = app_data_dir().map(|dir| dir.join("logs").join("video-export.log"));
    let cancel = Arc::new(AtomicBool::new(false));
    {
        *state
            .cancel
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(cancel.clone());
    }
    let job = RenderJob {
        options: export_options,
        output,
        encoder,
        bitrate_kbps,
        audio_only,
        log_path,
        encoder_name: Arc::new(Mutex::new(None)),
        app: Some(app),
        cancel: Some(cancel),
    };

    let result = tokio::task::spawn_blocking(move || job.run())
        .await
        .map_err(|error| format!("导出任务异常: {error}"))?;
    *state
        .cancel
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner()) = None;
    result
}

/// 取消正在进行的导出; 没有正在运行的任务时返回 `false`。
#[tauri::command]
pub fn cancel_video_export(state: State<'_, Arc<VideoExportState>>) -> bool {
    let guard = state
        .cancel
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    match guard.as_ref() {
        Some(flag) => {
            flag.store(true, Ordering::Relaxed);
            true
        }
        None => false,
    }
}

fn ensure_parent(path: &Path) -> Result<(), String> {
    if let Some(parent) = path.parent() {
        if !parent.as_os_str().is_empty() {
            std::fs::create_dir_all(parent)
                .map_err(|error| format!("无法创建输出目录 {}: {error}", parent.display()))?;
        }
    }
    Ok(())
}

/// 前端传进来的编码器选择；与渲染器后端解耦，便于非 Windows 构建也能编译。
#[derive(Debug, Clone, Copy)]
enum EncoderChoice {
    Auto,
    MediaFoundation,
    Ffmpeg,
}

/// 一次导出所需的全部参数（移动到阻塞任务里执行）。
struct RenderJob {
    options: ExportOptions,
    output: PathBuf,
    encoder: EncoderChoice,
    bitrate_kbps: u32,
    audio_only: bool,
    log_path: Option<PathBuf>,
    /// 渲染器回调报告的实际编码后端。
    encoder_name: Arc<Mutex<Option<String>>>,
    /// 用于把进度与预览帧推给前端。
    app: Option<AppHandle>,
    cancel: Option<Arc<AtomicBool>>,
}

impl RenderJob {
    fn run(self) -> Result<VideoExportResult, String> {
        let plan = build_plan(&self.options).map_err(|error| error.to_string())?;
        export_plan(&plan, &self)?;
        let encoder = self
            .encoder_name
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .clone();
        Ok(VideoExportResult {
            output: self.output.to_string_lossy().to_string(),
            encoder,
        })
    }
}

#[cfg(all(feature = "video-export", target_os = "windows"))]
fn export_plan(plan: &webgal_video_export::plan::Plan, job: &RenderJob) -> Result<(), String> {
    let builder = from_plan(plan).map_err(|error| error.to_string())?;
    let mut options = RenderOptions::new(&job.output);
    options.encoder = match job.encoder {
        EncoderChoice::Auto => Encoder::Auto,
        EncoderChoice::MediaFoundation => Encoder::MediaFoundation,
        EncoderChoice::Ffmpeg => Encoder::Ffmpeg,
    };
    options.audio_only = job.audio_only;
    options.bitrate_kbps = job.bitrate_kbps;
    options.live2d_core = live2d_core_file().filter(|path| path.is_file());
    options.log = job.log_path.clone();

    // 进度里的 `fps` 改成"实际渲染吞吐": 前端用它显示 `帧/s`, 与配置的目标帧率区分开。
    let started = std::cell::Cell::new(None::<std::time::Instant>);
    let progress = |progress: Progress<'_>| {
        if let Some(app) = &job.app {
            let now = std::time::Instant::now();
            let start = started.get().unwrap_or_else(|| {
                started.set(Some(now));
                now
            });
            let elapsed = now.duration_since(start).as_secs_f64();
            let measured = if elapsed > 0.0 {
                progress.current as f64 / elapsed
            } else {
                0.0
            };
            let payload = ProgressPayload {
                phase: progress.phase.to_owned(),
                current: progress.current,
                total: progress.total,
                fps: measured,
            };
            let _ = app.emit("video-export:progress", payload);
        }
    };
    let preview = |preview: Preview<'_>| {
        if let Some(app) = &job.app {
            let payload = PreviewPayload {
                frame: preview.frame,
                total: preview.total,
                data: format!("data:image/png;base64,{}", base64(preview.png)),
            };
            let _ = app.emit("video-export:preview", payload);
        }
    };
    let encoder_name = job.encoder_name.clone();
    let encoder_app = job.app.clone();
    let encoder = move |name: &str| {
        *encoder_name
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(name.to_owned());
        if let Some(app) = &encoder_app {
            let _ = app.emit("video-export:encoder", name.to_owned());
        }
    };
    let callbacks = Callbacks {
        progress: Some(&progress),
        preview: Some(&preview),
        encoder: Some(&encoder),
        cancel: job.cancel.as_deref(),
    };
    render(&builder, &options, callbacks).map_err(|error| error.to_string())
}

